import React, { useState, useEffect } from 'react';
import { Card, api } from '../App';

export default function LabelsPage() {
  const [saleNos,     setSaleNos]     = useState([]);
  const [selSale,     setSelSale]     = useState('');
  const [markings,    setMarkings]    = useState([]);
  const [histPrices,  setHistPrices]  = useState({});
  const [prevSaleNos, setPrevSaleNos] = useState([]);
  const [loading,     setLoading]     = useState(false);
  const [showHist,    setShowHist]    = useState(true);
  const [prevSales,   setPrevSales]   = useState(2);
  const [filterParty, setFilterParty] = useState('');
  const [filterGrade, setFilterGrade] = useState('');

  useEffect(() => {
    api.get('/import/sale-numbers')
      .then(r => { setSaleNos(r.data); if (r.data[0]) setSelSale(String(r.data[0].sale_no)); })
      .catch(() => {});
  }, []);

  const load = async (sale, pSales) => {
    if (!sale) return;
    setLoading(true);
    try {
      const [mRes, hRes] = await Promise.all([
        api.get(`/labels/markings?sale_no=${sale}`),
        api.get(`/labels/historical-prices?sale_no=${sale}&prev_sales=${pSales || prevSales}`)
      ]);
      setMarkings(mRes.data || []);
      setHistPrices(hRes.data.lookup || {});
      setPrevSaleNos(hRes.data.prev_sale_nos || []);
    } catch (e) { console.error(e); }
    finally { setLoading(false); }
  };

  const handleSaleChange = s => { setSelSale(s); load(s, prevSales); };
  const handlePrevChange = n => { setPrevSales(n); if (selSale) load(selSale, n); };

  // Deduplicate by party+garden+grade
  const seen = new Set();
  const unique = markings.filter(m => {
    const k = `${m.party_code}__${m.garden}__${m.grade}`;
    if (seen.has(k)) return false;
    seen.add(k); return true;
  });

  const parties = [...new Set(unique.map(m => m.party_code))].sort();
  const grades  = [...new Set(unique.map(m => m.grade))].sort();
  const filtered = unique.filter(m =>
    (!filterParty || m.party_code === filterParty) &&
    (!filterGrade || m.grade === filterGrade)
  );

  const getHist = (garden, grade) => histPrices[`${garden}__${grade}`] || null;

  const printLabels = () => {
    const win = window.open('', '_blank');

    // Build label HTML for print
    const labelsHtml = filtered.map(m => {
      const hist = getHist(m.garden, m.grade);
      const histSection = showHist && hist
        ? `<div class="hist">
             <span class="ht">Prev ${hist.from_sales.join('+')} Price:</span>
             <span class="low">&#8377;${hist.price_low}</span>&ndash;<span class="high">&#8377;${hist.price_high}</span>
           </div>`
        : '';
      const priceSection = m.final_price
        ? `<div class="price">&#8377;${parseFloat(m.final_price).toFixed(0)}</div>`
        : '';

      return `<div class="label">
        <div class="hdr">
          <span class="pname">${m.party_code}</span>
          <span class="sale">S#${m.sale_no}</span>
        </div>
        <div class="garden">${m.garden}</div>
        <div class="row2">
          <span class="grade">${m.grade}</span>
          <span class="bro">${m.broker || ''}</span>
        </div>
        <div class="row3">
          <span>${m.bags || '?'} bags</span>
          <span>${m.net_wt || '?'} kg</span>
        </div>
        <div class="row3">
          <span class="inv">${m.invoice_raw || m.invoice || ''}</span>
          ${priceSection}
        </div>
        ${histSection}
        <div class="origin">${m.origin || ''}</div>
      </div>`;
    }).join('');

    win.document.write(`<!DOCTYPE html>
<html><head><title>Labels Sale #${selSale}</title>
<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  body { font-family: Arial, Helvetica, sans-serif; background:#fff; font-size:6.5pt; }

  /* A4 page: 210x297mm, margins 5mm */
  @page { size: A4 portrait; margin: 5mm; }

  /* 6 columns x 8 rows = 48 per page */
  .grid {
    display: grid;
    grid-template-columns: repeat(6, 32.5mm);
    grid-auto-rows: 35mm;
    gap: 1mm;
    width: 200mm;
  }

  .label {
    width: 32.5mm;
    height: 35mm;
    border: 0.4pt solid #1a3c5e;
    border-radius: 1mm;
    padding: 1.2mm;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    gap: 0.6mm;
    page-break-inside: avoid;
  }

  .hdr {
    background: #1a3c5e;
    color: #fff;
    padding: 0.8mm 1.2mm;
    border-radius: 0.5mm;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-shrink: 0;
  }
  .pname { font-size: 7.5pt; font-weight: 900; letter-spacing: 0.2pt; }
  .sale  { font-size: 5.5pt; opacity: 0.8; }

  .garden {
    font-size: 7pt;
    font-weight: 800;
    color: #1a3c5e;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    flex-shrink: 0;
  }

  .row2 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-shrink: 0;
  }
  .grade {
    background: #dbeafe;
    color: #1e40af;
    padding: 0.3mm 1.5mm;
    border-radius: 3mm;
    font-size: 6.5pt;
    font-weight: 800;
  }
  .bro { font-size: 5.5pt; color: #6b7280; }

  .row3 {
    display: flex;
    justify-content: space-between;
    font-size: 6pt;
    color: #374151;
    font-weight: 600;
    flex-shrink: 0;
  }
  .inv { font-family: monospace; font-size: 5.5pt; color: #6b7280; }

  .price {
    font-size: 7.5pt;
    font-weight: 900;
    color: #1a3c5e;
  }

  .hist {
    background: #fffbeb;
    border: 0.4pt solid #fde68a;
    border-radius: 0.5mm;
    padding: 0.8mm 1mm;
    flex-shrink: 0;
  }
  .ht  { font-size: 5pt; color: #92400e; font-weight: 700; display: block; margin-bottom: 0.3mm; }
  .low { font-size: 6.5pt; font-weight: 800; color: #1a7a4a; }
  .high{ font-size: 6.5pt; font-weight: 800; color: #c0392b; }

  .origin {
    font-size: 5pt;
    color: #9ca3af;
    margin-top: auto;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  @media print {
    body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    .label { page-break-inside: avoid; }
  }
</style></head><body>
<div class="grid">${labelsHtml}</div>
</body></html>`);
    win.document.close();
    win.focus();
    setTimeout(() => { win.print(); win.close(); }, 500);
  };

  // Preview card style (screen representation — bigger for readability)
  const previewLabel = (m, idx) => {
    const hist = getHist(m.garden, m.grade);
    return (
      <div key={idx} style={{ width: 130, height: 140, border: '1.5px solid #1a3c5e', borderRadius: 5, padding: 6, display: 'flex', flexDirection: 'column', gap: 3, background: '#fff', boxShadow: '0 1px 4px rgba(0,0,0,0.08)', fontSize: 10, overflow: 'hidden' }}>
        <div style={{ background: '#1a3c5e', color: '#fff', padding: '3px 6px', borderRadius: 3, display: 'flex', justifyContent: 'space-between', flexShrink: 0 }}>
          <span style={{ fontWeight: 900, fontSize: 11 }}>{m.party_code}</span>
          <span style={{ fontSize: 9, opacity: 0.8 }}>S#{m.sale_no}</span>
        </div>
        <div style={{ fontWeight: 800, color: '#1a3c5e', fontSize: 10, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{m.garden}</div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ background: '#dbeafe', color: '#1e40af', padding: '1px 5px', borderRadius: 99, fontSize: 9, fontWeight: 700 }}>{m.grade}</span>
          <span style={{ fontSize: 8, color: '#6b7280' }}>{m.broker}</span>
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 9, color: '#374151', fontWeight: 600 }}>
          <span>{m.bags || '?'} bags</span>
          <span>{m.net_wt || '?'} kg</span>
        </div>
        {m.final_price && (
          <div style={{ fontWeight: 900, color: '#1a3c5e', fontSize: 11 }}>₹{parseFloat(m.final_price).toFixed(0)}</div>
        )}
        {showHist && hist && (
          <div style={{ background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 3, padding: '2px 4px', fontSize: 9 }}>
            <div style={{ fontSize: 8, color: '#92400e', fontWeight: 700 }}>Prev {hist.from_sales.join('+')}:</div>
            <span style={{ color: '#1a7a4a', fontWeight: 800 }}>₹{hist.price_low}</span>
            <span style={{ color: '#9ca3af' }}> – </span>
            <span style={{ color: '#c0392b', fontWeight: 800 }}>₹{hist.price_high}</span>
          </div>
        )}
        <div style={{ fontSize: 8, color: '#9ca3af', marginTop: 'auto', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{m.origin || ''}</div>
      </div>
    );
  };

  return (
    <div>
      <h2 style={{ marginBottom: 2, color: '#1a3c5e', fontSize: 20, fontWeight: 800 }}>🏷 Print Labels</h2>
      <p style={{ color: '#9ca3af', fontSize: 12, marginBottom: 14 }}>
        48 labels per A4 page — 6 columns × 8 rows (32.5mm × 35mm each, 5mm page margins)
      </p>

      <Card style={{ marginBottom: 14, padding: 14 }}>
        <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start', flexWrap: 'wrap' }}>
          {/* Sale */}
          <div>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#6b7280', marginBottom: 4, textTransform: 'uppercase' }}>Sale Number</label>
            <select value={selSale} onChange={e => handleSaleChange(e.target.value)}
              style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 200 }}>
              <option value="">Select sale...</option>
              {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
            </select>
          </div>

          {/* Historical price */}
          <div style={{ padding: '10px 14px', background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 8 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: '#92400e', marginBottom: 6 }}>📊 Historical Price (Optional)</div>
            <label style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6, cursor: 'pointer' }}>
              <input type="checkbox" checked={showHist} onChange={e => setShowHist(e.target.checked)} style={{ width: 14, height: 14, accentColor: '#f59e0b' }} />
              <span style={{ fontSize: 12, fontWeight: 600, color: '#92400e' }}>Include prev sale price range on label</span>
            </label>
            {showHist && (
              <div>
                <div style={{ fontSize: 10, color: '#b45309', marginBottom: 4, fontWeight: 600 }}>Previous sales to include:</div>
                <div style={{ display: 'flex', gap: 5 }}>
                  {[1,2,3,4].map(n => (
                    <button key={n} onClick={() => handlePrevChange(n)}
                      style={{ padding: '3px 10px', borderRadius: 4, fontSize: 11, fontWeight: 700, cursor: 'pointer',
                        background: prevSales === n ? '#f59e0b' : '#fef3c7',
                        color: prevSales === n ? '#fff' : '#92400e',
                        border: `1.5px solid ${prevSales === n ? '#f59e0b' : '#fde68a'}` }}>{n}</button>
                  ))}
                </div>
                {prevSaleNos.length > 0 && (
                  <div style={{ fontSize: 9, color: '#b45309', marginTop: 4 }}>Using: Sale {prevSaleNos.join(', ')}</div>
                )}
              </div>
            )}
          </div>

          {/* Filters */}
          <div>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#6b7280', marginBottom: 4, textTransform: 'uppercase' }}>Party</label>
            <select value={filterParty} onChange={e => setFilterParty(e.target.value)}
              style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 5, fontSize: 12, minWidth: 140 }}>
              <option value="">All Parties</option>
              {parties.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>
          <div>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#6b7280', marginBottom: 4, textTransform: 'uppercase' }}>Grade</label>
            <select value={filterGrade} onChange={e => setFilterGrade(e.target.value)}
              style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 5, fontSize: 12, minWidth: 110 }}>
              <option value="">All Grades</option>
              {grades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
          </div>
        </div>

        {filtered.length > 0 && (
          <div style={{ marginTop: 14, display: 'flex', alignItems: 'center', gap: 12 }}>
            <button onClick={printLabels}
              style={{ padding: '8px 22px', background: '#1a3c5e', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontWeight: 700, fontSize: 13 }}>
              🖨 Print {filtered.length} Labels ({Math.ceil(filtered.length/48)} page{filtered.length > 48 ? 's' : ''})
            </button>
            <span style={{ fontSize: 11, color: '#6b7280' }}>
              48 per A4 · 6×8 grid · 32.5×35mm each
            </span>
          </div>
        )}
      </Card>

      {loading && <Card style={{ padding: 30, textAlign: 'center', color: '#888' }}>⏳ Loading...</Card>}

      {!loading && !filtered.length && selSale && (
        <Card style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>No markings found for Sale #{selSale}</Card>
      )}

      {!loading && filtered.length > 0 && (
        <div>
          <div style={{ fontSize: 12, color: '#6b7280', marginBottom: 10, fontWeight: 600 }}>
            Preview — {filtered.length} labels
            <span style={{ fontSize: 10, fontWeight: 400, marginLeft: 8 }}>(screen preview is larger than actual print size)</span>
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
            {filtered.map((m, i) => previewLabel(m, i))}
          </div>
        </div>
      )}
    </div>
  );
}
